CREATE TABLE `ml_race_simulation_driver_summaries` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key.',
  `ml_race_simulation_batch_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to ml_race_simulation_batches.',
  `car_driver_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to cars_drivers for the simulated entry.',
  `n_simulations` int(10) unsigned NOT NULL COMMENT 'Draws aggregated into this summary; must match the batch n_simulations.',
  `mean_dfs_points` decimal(14,3) NOT NULL COMMENT 'Mean simulated DraftKings points.',
  `std_dfs_points` decimal(14,3) NOT NULL COMMENT 'Standard deviation of simulated DraftKings points.',
  `min_dfs_points` decimal(14,3) NOT NULL COMMENT 'Minimum simulated DraftKings points.',
  `p05_dfs_points` decimal(14,3) NOT NULL COMMENT '5th percentile of simulated DraftKings points.',
  `p50_dfs_points` decimal(14,3) NOT NULL COMMENT 'Median (50th percentile) simulated DraftKings points.',
  `p95_dfs_points` decimal(14,3) NOT NULL COMMENT '95th percentile of simulated DraftKings points.',
  `max_dfs_points` decimal(14,3) NOT NULL COMMENT 'Maximum simulated DraftKings points.',
  `mean_r_finish_position` decimal(14,3) NOT NULL COMMENT 'Mean simulated finish position (1 = winner; tail-permuted for DNFed iterations).',
  `std_r_finish_position` decimal(14,3) NOT NULL COMMENT 'Standard deviation of simulated finish position.',
  `min_r_finish_position` decimal(14,3) NOT NULL COMMENT 'Best (lowest) simulated finish position.',
  `p05_r_finish_position` decimal(14,3) NOT NULL COMMENT '5th percentile simulated finish position (high-ceiling outcome).',
  `p50_r_finish_position` decimal(14,3) NOT NULL COMMENT 'Median simulated finish position.',
  `p95_r_finish_position` decimal(14,3) NOT NULL COMMENT '95th percentile simulated finish position (worst-case bucket, includes DNFed tails).',
  `max_r_finish_position` decimal(14,3) NOT NULL COMMENT 'Worst (highest) simulated finish position.',
  `mean_r_total_fastest_laps` decimal(14,3) NOT NULL COMMENT 'Mean simulated fastest-laps count (post-constraint; scaled by completion fraction for DNFed iterations).',
  `std_r_total_fastest_laps` decimal(14,3) NOT NULL COMMENT 'Standard deviation of simulated fastest-laps count.',
  `min_r_total_fastest_laps` decimal(14,3) NOT NULL COMMENT 'Minimum simulated fastest-laps count.',
  `p05_r_total_fastest_laps` decimal(14,3) NOT NULL COMMENT '5th percentile simulated fastest-laps count.',
  `p50_r_total_fastest_laps` decimal(14,3) NOT NULL COMMENT 'Median simulated fastest-laps count.',
  `p95_r_total_fastest_laps` decimal(14,3) NOT NULL COMMENT '95th percentile simulated fastest-laps count.',
  `max_r_total_fastest_laps` decimal(14,3) NOT NULL COMMENT 'Maximum simulated fastest-laps count.',
  `mean_r_total_laps_led` decimal(14,3) NOT NULL COMMENT 'Mean simulated laps-led count (post-constraint; scaled by completion fraction for DNFed iterations).',
  `std_r_total_laps_led` decimal(14,3) NOT NULL COMMENT 'Standard deviation of simulated laps-led count.',
  `min_r_total_laps_led` decimal(14,3) NOT NULL COMMENT 'Minimum simulated laps-led count.',
  `p05_r_total_laps_led` decimal(14,3) NOT NULL COMMENT '5th percentile simulated laps-led count.',
  `p50_r_total_laps_led` decimal(14,3) NOT NULL COMMENT 'Median simulated laps-led count.',
  `p95_r_total_laps_led` decimal(14,3) NOT NULL COMMENT '95th percentile simulated laps-led count.',
  `max_r_total_laps_led` decimal(14,3) NOT NULL COMMENT 'Maximum simulated laps-led count.',
  `dnf_pct` decimal(5,4) NOT NULL COMMENT 'Fraction of simulated iterations where the driver DNFed; equals the per-driver Bernoulli(P_dnf) empirical mean. Zero when the two-stage DNF classifier was inactive for this snapshot.',
  `created_at` timestamp NULL DEFAULT current_timestamp() COMMENT 'Creation timestamp.',
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Last update timestamp.',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT 'Soft-delete timestamp; NULL means active.',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci COMMENT='Per-driver Monte Carlo distribution summaries for one batch (DFS points, sampled targets, and DNF rate).';
